def parse_money(s: str) -> float | None:
    # Remove whitespace and handle empty strings or "n/a"
    s = s.strip()
    if s == "" or s.lower() == "n/a":
        return None

    try:
        # Remove leading $ if present
        if s.startswith('$'):
            s = s[1:]

        # Convert to float (handles standard decimal notation)
        return float(s)
    except ValueError:
        return None
